// Package version provides the ordering metadata attached to every cache
// write: a hybrid logical clock (HLC) timestamp plus the ID of the node that
// coordinated the write.
//
// Ordering is last-writer-wins (LWW) by (T, Node). T is generated by the
// coordinating node's HLC, which never goes backwards locally and is advanced
// whenever the node observes a higher timestamp from a peer. This bounds the
// damage of clock skew (a node never issues a version lower than one it has
// already seen) but does not eliminate it: two coordinators writing the same
// key concurrently are ordered by their clocks, not by real time.
package version

import (
	"sync"
	"time"
)

// logicalBits is the number of low-order bits reserved for the logical
// counter. 16 bits allow 65536 versions per millisecond per node.
const logicalBits = 16

// Version orders writes to a single key.
type Version struct {
	T    uint64 `json:"t"`
	Node string `json:"n,omitempty"`
}

// IsZero reports whether v is the zero version (no write).
func (v Version) IsZero() bool { return v.T == 0 && v.Node == "" }

// Compare returns -1, 0 or +1. Higher T wins; ties are broken by node ID so
// that every replica resolves the same conflict the same way.
func (v Version) Compare(o Version) int {
	switch {
	case v.T < o.T:
		return -1
	case v.T > o.T:
		return 1
	case v.Node < o.Node:
		return -1
	case v.Node > o.Node:
		return 1
	}
	return 0
}

// Newer reports whether v is strictly newer than o.
func (v Version) Newer(o Version) bool { return v.Compare(o) > 0 }

// PhysicalTime extracts the wall-clock component of an HLC timestamp.
func PhysicalTime(t uint64) time.Time {
	return time.UnixMilli(int64(t >> logicalBits))
}

// Clock is a hybrid logical clock. It is safe for concurrent use.
type Clock struct {
	mu   sync.Mutex
	last uint64
	now  func() time.Time
}

// NewClock returns a clock backed by now (time.Now if nil).
func NewClock(now func() time.Time) *Clock {
	if now == nil {
		now = time.Now
	}
	return &Clock{now: now}
}

// Next returns a timestamp strictly greater than any previously issued or
// observed timestamp.
func (c *Clock) Next() uint64 {
	c.mu.Lock()
	defer c.mu.Unlock()
	phys := uint64(c.now().UnixMilli()) << logicalBits
	if phys > c.last {
		c.last = phys
	} else {
		c.last++
	}
	return c.last
}

// Observe advances the clock so that later calls to Next exceed t.
func (c *Clock) Observe(t uint64) {
	c.mu.Lock()
	if t > c.last {
		c.last = t
	}
	c.mu.Unlock()
}
